    private static final int ARRAY_WIDTH = 50;
    private static final int ARRAY_HEIGHT = 50;
    private static final int SCALE = 2;

    private static final int OFFSET_X = 30;
    private static final int OFFSET_Y = 22;

    public void draw(PixelDisplay graphic) {
        for (var row = 0; row < ARRAY_HEIGHT; row++) {
            for (var col = 0; col < ARRAY_WIDTH; col++) {
                var color = toColor(ARRAY[row][col]);
                if (color == null) {
                    continue;
                }
                for (var sx = 0; sx < SCALE; sx++) {
                    for (var sy = 0; sy < SCALE; sy++) {
                        var px = col * SCALE + sx + OFFSET_X;
                        var py = row * SCALE + sy + OFFSET_Y;
                        if (px < graphic.getPixelWidth() && py < graphic.getPixelHeight()) {
                            graphic.setPixel(px, py, color);
                        }
                    }
                }
            }
        }
    }

    private PixelColor toColor(int value) {
        return switch (value) {
            case 0, 3 -> PixelColor.BLACK;
            case 1 -> PixelColor.LOW;
            case 4 -> PixelColor.HIGH;
            default -> null;
        };
    }
